document.querySelectorAll('.ipc').forEach(group => {
  const dots = [...group.querySelectorAll('button')];
  const show = (i, focus) => {
    dots.forEach((d, k) => { d.setAttribute('aria-current', String(k === i)); d.tabIndex = k === i ? 0 : -1; });
    if (focus) dots[i].focus();
  };
  dots.forEach((d, i) => d.addEventListener('click', () => show(i)));
  group.addEventListener('keydown', e => {
    const i = dots.indexOf(document.activeElement); if (i < 0) return;
    const n = { ArrowRight: (i + 1) % dots.length, ArrowLeft: (i - 1 + dots.length) % dots.length }[e.key];
    if (n !== undefined) { e.preventDefault(); show(n, true); }
  });
  show(dots.findIndex(d => d.getAttribute('aria-current') === 'true'));
});
